      background: var(--color-pistachio);
    }

    .hours-status.is-closed .hours-status__dot {
      background: var(--color-raspberry);
    }

    .visit__actions {
      display: flex;
      flex-wrap: wrap;
      gap: .7rem;
      margin-top: 1.4rem;
    }

    .visit .button--light {
      border-color: rgba(255,255,255,.25);
      color: var(--color-white);
    }

    .visit .button--light:hover {
      background: rgba(255,255,255,.1);
    }

    /* SECTIONS: FINAL CTA */
    .final-cta {
      padding-block: var(--space-8);
      text-align: center;
    }

    .final-cta__inner { max-width: 760px; margin-inline: auto; }

    .final-cta__title {
      margin: 1.2rem 0;
      color: var(--color-ink);
      font-family: var(--font-display);
      font-size: clamp(3.3rem, 8vw, 7rem);
      font-weight: 400;
      letter-spacing: -.06em;
      line-height: .94;
    }

    .final-cta__title em { color: var(--color-raspberry); }

    .final-cta__text {
      max-width: 470px;
      margin: 0 auto 1.8rem;
      color: var(--color-muted);
    }

    /* SECTIONS: FOOTER */
    .site-footer {
      padding-block: 2rem;
      background: var(--color-pistachio);
      color: var(--color-ink);
    }

    .footer__inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1.5rem;
    }

    .footer__brand {
      font-size: 1.2rem;
      font-weight: 800;
      letter-spacing: -.06em;
    }

    .footer__meta {
      margin-top: .25rem;
      font-size: .75rem;
    }

    .footer__links {
      display: flex;
      flex-wrap: wrap;
      gap: 1.2rem;
    }

    .footer__links a {
      font-size: .78rem;
      font-weight: 800;
      text-decoration: none;
    }

    /* MOTION */
    @keyframes marquee {
      to { transform: translateX(-50%); }
    }

    @keyframes dessert-float {
      0%, 100% { transform: translateY(0) rotate(-2deg); }
      50% { transform: translateY(-12px) rotate(2deg); }
    }

    /* RESPONSIVE */
    @media (min-width: 1500px) {
      :root { --gutter: 8%; }
    }

    @media (max-width: 900px) {
      .hero__grid { grid-template-columns: 1fr 1fr; gap: 1.5rem; }
      .hero__title { font-size: clamp(3.6rem, 8vw, 5.5rem); }
      .hero__art { min-height: 380px; }
      .hero__sticker { width: 82px; font-size: .65rem; }
      .menu-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .signature__grid { gap: 1.5rem; }
      .experience__grid { gap: 2rem; }
      .experience__visual { min-height: 330px; }
    }

    @media (max-width: 650px) {
      :root {
        --gutter: 5%;
        --space-8: 4.5rem;
      }

      .header__inner { min-height: 72px; }
      .header__nav { display: none; }
      .header__action { min-height: 43px; padding-inline: 1rem; font-size: .78rem; }

      .hero { padding-block: 3.3rem 4rem; }
      .hero__grid { grid-template-columns: 1fr; gap: .5rem; }
      .hero__title { font-size: clamp(4rem, 15vw, 6rem); }
      .hero__description { max-width: 370px; }
      .hero__art { min-height: 360px; margin-top: .5rem; }
      .dessert { width: min(72%, 275px); }
      .hero__sticker { right: 5%; }
      .hero__caption { left: 5%; bottom: 1%; }

      .intro__inner { align-items: flex-start; flex-direction: column; gap: 1rem; }
      .intro__link { padding-block: .3rem; }

      .section-top { align-items: flex-start; flex-direction: column; gap: 1rem; margin-bottom: 2rem; }
      .menu-grid { grid-template-columns: 1fr; gap: .9rem; }
      .menu-card { min-height: 300px; }
      .menu-card__visual { width: 55%; right: 1%; }
      .menu-card__title { font-size: 2.6rem; }

      .signature__grid { grid-template-columns: 1fr; }
      .signature__art { min-height: 300px; }
      .signature__circle { width: min(75%, 290px); }

      .experience__grid { grid-template-columns: 1fr; }
      .experience__visual { min-height: 310px; }

      .visit__grid { grid-template-columns: 1fr; gap: 1rem; }
      .visit-card { padding: 1.5rem; }

      .footer__inner { align-items: flex-start; flex-direction: column; }
      .footer__links { gap: 1rem; }
    }

    @media (max-width: 380px) {
      .hero__title { font-size: 3.7rem; }
      .hero__actions { align-items: stretch; flex-direction: column; }
      .hero__actions .button { width: 100%; }
      .hero__art { min-height: 310px; }
      .hours-list__row { font-size: .74rem; }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        scroll-behavior: auto !important;
        animation-duration: .01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: .01ms !important;
      }

      .reveal {
        opacity: 1;
        transform: none;
      }
    }
